import { errorMessage } from "./text.js";

export async function resolveDns(e, t = !1) {
    const r = `https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(e)}`, n = { ipv4: `${r}&type=A`, ipv6: `${r}&type=AAAA` };
    try {
        const e = await queryDohJson(n.ipv4, 1), r = void 0;
        return { ipv4: e, ipv6: t ? [] : await queryDohJson(n.ipv6, 28) };
    }
    catch (t) {
        throw new Error(`Error resolving DNS for ${e}: ${errorMessage(t)}`);
    }
}

export async function queryDohJson(e, t) {
    try {
        const r = await fetch(e, { headers: { accept: "application/dns-json" } }), n = await r.json();
        return n.Answer ? n.Answer.filter(e => e.type === t).map(e => e.data) : [];
    }
    catch (t) {
        throw new Error(`Failed to fetch DNS records from ${e}: ${errorMessage(t)}`);
    }
}
