// Part of the VLESS/Trojan panel (fork of BPB Worker Panel by bia-pain-bache).
// Array/Object helpers used by the config builders (kept for byte-identical output).
Array.prototype.concatIf = function (e, t) { return e ? Array.isArray(t) ? [...this, ...t] : [...this, t] : this; };
Object.prototype.omitEmpty = function () {
    if (0 !== Object.keys(this).length)
        return this;
};
