export function utf8ToBase64(e) { const t = (new TextEncoder).encode(e), r = Array.from(t, e => String.fromCharCode(e)).join(""); return btoa(r); }

export function base64ToUtf8(e) { return (new TextDecoder).decode(Uint8Array.from(atob(e), e => e.charCodeAt(0))); }

export function randomCase(e) {
    let t = "";
    for (let r = 0; r < e.length; r++)
        t += Math.random() < .5 ? e[r].toUpperCase() : e[r];
    return t;
}

export function randomString(e, t) {
    let r = "";
    const n = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789", a = Math.floor(Math.random() * (t - e + 1)) + e;
    for (let e = 0; e < a; e++)
        r += n.charAt(Math.floor(62 * Math.random()));
    return r;
}

export function formatRange(e, t) {
    if (e && t)
        return e === t ? String(e) : `${e}-${t}`;
}

export function errorMessage(e) { return e instanceof Error ? e.message : String(e); }
