import { getContext } from "../context.js";
import { errorMessage } from "./text.js";
import { ERROR_HTML } from "../ui/generated.js";

export function jsonResponse(e, t, r, n, a) { const o = { "Content-Type": "application/json", ...a }, s = { success: e, status: t, message: r ?? null, body: n ?? null }; return new Response(JSON.stringify(s), { status: t, headers: o }); }

export async function renderErrorPage(e) {
    const t = String(errorMessage(e)).replace(/[&<>"']/g, e => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[e]));
    return new Response(ERROR_HTML.replace("__ERROR_MESSAGE__", t), { headers: { "Content-Type": "text/html; charset=utf-8" } });
}

export async function proxyDoh(e) { const { dohUrl: t, searchParams: r } = getContext(), n = new URL(t); r.forEach((e, t) => { n.searchParams.set(t, e); }); const a = new Request(n.toString(), e); return fetch(a); }

export async function fallbackHandler(e) {
    const { url: t, method: r, headers: n, body: a } = e, { fallback: o } = getContext();
    if (!o)
        return new Response("Not Found", { status: 404 });
    const s = new URL(t);
    s.hostname = o, s.protocol = "https:";
    const i = new Request(s.toString(), { method: r, headers: n, body: a, redirect: "manual" });
    return fetch(i);
}
