// Part of the VLESS/Trojan panel (fork of BPB Worker Panel by bia-pain-bache).
import { getContext, getFixedSettings } from "../context.js";
import { fallbackHandler, jsonResponse } from "../lib/http.js";
import { errorMessage } from "../lib/text.js";
import { SUBSCRIPTIONS, SUPPORTED_CLIENTS } from "../settings/defaults.js";
import { loadSettings, saveSettings } from "../settings/store.js";
import { validateSettings } from "../settings/validation.js";
import { PANEL_HTML } from "../ui/generated.js";

export async function routePanel(e, t) {
    const { pathname: r } = getContext();
    switch (r.split("/").slice(2).join("/")) {
        case "panel": return servePanelPage();
        case "panel/settings": return handleGetSettings(e, t);
        case "panel/update-settings": return handleUpdateSettings(e, t);
        case "panel/reset-settings": return handleResetSettings(e, t);
        default: return fallbackHandler(e);
    }
}

export async function servePanelPage() {
    return new Response(PANEL_HTML, { headers: { "Content-Type": "text/html; charset=utf-8" } });
}

export async function handleGetSettings(e, t) {
    try {
        const { settings: a } = await loadSettings(t);
        return jsonResponse(!0, 200, void 0, { proxySettings: { ...a, ...getFixedSettings() }, subscriptions: SUBSCRIPTIONS, clients: SUPPORTED_CLIENTS }, { "Content-Type": "application/json", "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0", Pragma: "no-cache", Expires: "0" });
    }
    catch (e) {
        return console.log(e), jsonResponse(!1, 500, `Error occurred while fetching settings: ${errorMessage(e)}`);
    }
}

export async function handleUpdateSettings(e, t) {
    if ("PUT" !== e.method)
        return jsonResponse(!1, 405, "Method not allowed.");
    try {
        const n = await e.json(), a = validateSettings(n);
        if (a)
            return jsonResponse(!1, 400, "Validation Error", a);
        await saveSettings(t, n);
        return jsonResponse(!0, 200, "");
    }
    catch (e) {
        return console.log(e), jsonResponse(!1, 500, errorMessage(e));
    }
}

export async function handleResetSettings(e, t) {
    if ("POST" !== e.method)
        return jsonResponse(!1, 405, "Method not allowed!");
    try {
        const n = await saveSettings(t);
        return jsonResponse(!0, 200, "", { ...n, ...getFixedSettings() });
    }
    catch (e) {
        return console.log(e), jsonResponse(!1, 500, `Error occurred while resetting settings: ${errorMessage(e)}`);
    }
}
