import { CONFIG } from "./config.js";
import { _public_proxy_ip_ } from "./constants.js";
import { DEFAULTS } from "./settings/defaults.js";

export let currentSettings = { ...DEFAULTS };

export let requestContext;

export const getContext = () => requestContext;

export const getDefaultSettings = () => DEFAULTS;

export const getSettings = () => ({ ...currentSettings, ...requestContext });

export function getFixedSettings() { const { mainDomain: e, ...t } = CONFIG; return t; }

export function initContext(e) {
    if (!CONFIG.vlUUID || !CONFIG.trPass || !CONFIG.securePath)
        throw new Error("Please set vlUUID, trPass and securePath in CONFIG.");
    const { pathname: r, origin: n, searchParams: a, hostname: o } = new URL(e.url);
    setContext({
        vlUUID: CONFIG.vlUUID,
        trPass: CONFIG.trPass,
        securePath: CONFIG.securePath,
        proxyIpMode: CONFIG.proxyIpMode,
        proxyIPs: CONFIG.proxyIPs.length ? CONFIG.proxyIPs : [_public_proxy_ip_],
        prefixes: CONFIG.prefixes.length ? CONFIG.prefixes : ["[2a02:898:146:64::]", "[2602:fc59:b0:64::]", "[2602:fc59:11:64::]"],
        mainDomain: CONFIG.mainDomain || o,
        fallback: CONFIG.fallback,
        dohUrl: CONFIG.dohUrl || "https://cloudflare-dns.com/dns-query",
        httpPorts: [80, 8080, 2052, 2082, 2086, 2095, 8880],
        httpsPorts: [443, 8443, 2053, 2083, 2087, 2096],
        client: decodeURIComponent(a.get("app") ?? ""),
        origin: n,
        searchParams: a,
        pathname: decodeURIComponent(r),
        hostname: o
    });
}

export const getCurrentSettings = () => currentSettings;

export const setCurrentSettings = (s) => { currentSettings = s; };

export const setContext = (c) => { requestContext = c; };
