import "./lib/prototypes.js";
import { getContext, initContext } from "./context.js";
import { fallbackHandler, proxyDoh, renderErrorPage } from "./lib/http.js";
import { handleWebSocket } from "./proxy/index.js";
import { routePanel } from "./routes/panel.js";
import { routeSubscription } from "./routes/subscription.js";

export default {
    async fetch(e, t) {
        try {
            initContext(e);
            if ("websocket" === e.headers.get("Upgrade"))
                return handleWebSocket(e);
            const { securePath: r, pathname: n } = getContext();
            switch (n.split("/").splice(0, 3).join("/")) {
                case `/${r}/panel`: return routePanel(e, t);
                case `/${r}/sub`: return routeSubscription(e, t);
                case `/${r}/dns-query`: return proxyDoh(e);
                default: return fallbackHandler(e);
            }
        }
        catch (e) {
            console.error("WORKER_ERROR:", e && (e.stack || e.message || String(e)));
            return renderErrorPage(e);
        }
    }
};
