// Part of the VLESS/Trojan panel (fork of BPB Worker Panel by bia-pain-bache).
import { getContext } from "../context.js";
import { fallbackHandler } from "../lib/http.js";
import { handleTrojanSocket } from "./trojan.js";
import { handleVlessSocket } from "./vless.js";

export async function handleWebSocket(e) {
    const { pathname: t } = getContext(), r = t.split("/")[1];
    try {
        switch (r) {
            case "vl": return handleVlessSocket(e);
            case "tr": return handleTrojanSocket(e);
            default: return fallbackHandler(e);
        }
    }
    catch (e) {
        return new Response("Bad Request", { status: 400 });
    }
}
