import { resolveDns } from "../lib/dns.js";
import { isIPv4 } from "../lib/validators.js";

export async function resolveNat64Address(e, t) {
    let r = e;
    if (!isIPv4(e)) {
        const { ipv4: t } = await resolveDns(e, !0);
        if (!t.length)
            throw new Error("Unable to find IPv4 in DNS records");
        r = t[0];
    }
    return ipv4ToNat64(r, t);
}

export function ipv4ToNat64(e, t) {
    const r = e.split(".");
    if (4 !== r.length)
        throw new Error("Invalid IPv4 address");
    const n = r.map(e => {
        const t = parseInt(e, 10);
        if (t < 0 || t > 255)
            throw new Error("Invalid IPv4 address");
        return t.toString(16).padStart(2, "0");
    }), a = t.match(/^\[([0-9A-Fa-f:]+)\]$/);
    if (a)
        return `[${a[1]}${n[0]}${n[1]}:${n[2]}${n[3]}]`;
}
