export function isIPv4OrCidr(e) { return /^(?:(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d\d?)(?:\/(?:[0-9]|[1-2][0-9]|3[0-2]))?$/.test(e); }

export function isIPv6(e) { return /^(?:(?:[a-fA-F0-9]{1,4}:){7}[a-fA-F0-9]{1,4}|(?:[a-fA-F0-9]{1,4}:){1,7}:|(?:[a-fA-F0-9]{1,4}:){1,6}:[a-fA-F0-9]{1,4}|(?:[a-fA-F0-9]{1,4}:){1,5}(?::[a-fA-F0-9]{1,4}){1,2}|(?:[a-fA-F0-9]{1,4}:){1,4}(?::[a-fA-F0-9]{1,4}){1,3}|(?:[a-fA-F0-9]{1,4}:){1,3}(?::[a-fA-F0-9]{1,4}){1,4}|(?:[a-fA-F0-9]{1,4}:){1,2}(?::[a-fA-F0-9]{1,4}){1,5}|[a-fA-F0-9]{1,4}:(?::[a-fA-F0-9]{1,4}){1,6}|:(?::[a-fA-F0-9]{1,4}){1,7}|::)(?:\/(?:12[0-8]|1[01]?[0-9]|[0-9]?[0-9]))?$/.test(e); }

export function isHttpUrl(e) {
    try {
        const t = new URL(e);
        return "http:" === t.protocol || "https:" === t.protocol;
    }
    catch (e) {
        return !1;
    }
}

export function isBase64(e) { return !(!e || e.length % 4 != 0) && /^[A-Za-z0-9+/=\r\n]+$/.test(e); }

export function isHex(e) { return /^(?=(?:[0-9A-Fa-f]{2})*$)[0-9A-Fa-f]+$/.test(e); }

export function parseUrlHost(e) {
    try {
        const t = void 0, r = new URL(e).hostname, n = void 0;
        return { host: r, isHostDomain: isDomain(r) };
    }
    catch {
        return { host: "", isHostDomain: !1 };
    }
}

export function parseHostPort(e, t) {
    const r = /^(?:\[(?<ipv6>.+?)\]|(?<host>[^:]+))(:(?<port>\d+))?$/, n = e.match(r);
    if (!n || !n.groups)
        return { host: "", port: 0 };
    const { ipv6: a, host: o, port: s } = n.groups;
    let i = a ?? o ?? "";
    t && a && (i = `[${a}]`);
    return { host: i, port: s ? Number(s) : 0 };
}

export function isHttpsPort(e) { const { httpsPorts: t } = getSettings(); return t.includes(e); }
